const { createClient } = require('@supabase/supabase-js');
const supabase = createClient('https://vgujnkxylipfwmkpwzvb.supabase.co', process.env.SUPABASE_SERVICE_KEY);

const transcripts = {
  '4c051c41-d747-47f9-920e-0e89afd61967': `Welcome to Module 3, Lesson 3.1 — Automated Meeting Summaries with Otter.ai and Fireflies. If I could give every project manager and Scrum Master only one AI tool, it would be automated meeting transcription and summarization. The ROI is immediate, the setup is simple, and the impact on team alignment is profound. Let me explain why this matters so much. The average project manager spends 4 to 6 hours per week in meetings. After each meeting, someone needs to capture decisions, action items, and key discussion points. That documentation task takes another 30 to 60 minutes per meeting if done properly. Multiply that across your weekly ceremonies and stakeholder meetings, and you are spending 2 to 3 hours per week just on post-meeting documentation. Otter.ai and Fireflies eliminate most of that time. Both tools join your meetings as a participant, transcribe everything in real time, and then generate structured summaries including key decisions, action items with suggested owners, and topics discussed. The transcription accuracy for clear audio is typically 90 to 95 percent, which is more than sufficient for practical use. The setup takes about 20 minutes. Connect the tool to your Google Calendar or Outlook, authorize it to join meetings automatically, and configure your summary template to match your team's preferred format. I recommend customizing the summary template to explicitly capture Sprint Goal status for Scrum ceremonies and risk flags for stakeholder meetings. Once set up, here is your new workflow: you focus entirely on facilitating and participating in the meeting, knowing that documentation is happening automatically. Immediately after the meeting ends, you receive a summary that you review, edit for context that the AI missed, and share with stakeholders within minutes. The quality of your meeting documentation goes up while your effort goes down. Teams using automated meeting summaries consistently report better action item follow-through because every action item is documented with an owner and visible to the whole team, and better stakeholder trust because communication is faster and more consistent.`,

  'd5626e4e-e60b-4664-a990-2fb77a409d46': `Lesson 3.2 — Stakeholder Reports and Status Updates with AI. Status reporting is one of the most universally dreaded tasks in project management. It is time-consuming, it requires translating complex technical reality into executive-friendly language, and it needs to be done consistently even when you are under pressure from a difficult sprint or a stakeholder escalation. AI transforms status reporting from a chore into a five-minute task. Here is how. The key to great AI-generated status reports is giving the AI the right inputs. Before asking AI to write anything, compile your raw data: sprint velocity and completion rate, key accomplishments from the current period, blockers and their resolution status, upcoming milestones and their confidence levels, and any risks that need stakeholder awareness. With these inputs, a well-crafted prompt produces a professional status report in seconds. The prompt structure I use: you are a senior project manager writing a weekly status update for executive stakeholders. The audience has limited technical context and needs a clear understanding of project health, key decisions needed, and risks requiring attention. Use the following data and write a status report with RAG status, executive summary, accomplishments, upcoming milestones, risks and mitigations, and decisions needed. Then paste your raw data. The output will need light editing for tone and context, but the structure and language will be professional and appropriate for your audience. One important principle: never let AI make up status information. Only put verified facts into the prompt. AI is excellent at formatting and communicating your data — it is not a substitute for actually knowing what is happening on your project. Use AI to communicate reality more effectively, not to obscure it. Teams that adopt AI status reporting consistently send updates faster, receive fewer follow-up questions because the reports are more comprehensive, and report less stress around the reporting process.`,

  '33b2c8dc-1b2a-4c3a-ada3-157247821663': `Lesson 3.3 — Sprint Review and Demo Preparation with AI. Sprint Reviews are high-stakes events. Stakeholders are watching, leadership is evaluating, and your team's morale is significantly affected by how well the review goes. Yet preparation for Sprint Reviews is often rushed — teams spend the last day of the sprint scrambling to prepare slides, write talking points, and organize the demo flow. AI can dramatically reduce that preparation burden. Let me walk you through an AI-assisted Sprint Review preparation workflow. The week before the review, use AI to generate a first draft of your Sprint Review presentation structure based on the Sprint Goal, the stories completed, and the stories not completed with explanations. This gives you a structured skeleton that you fill in with team-specific details rather than building from a blank slide. For the demo flow, use AI to help script the narrative that connects individual feature demonstrations to the business value they deliver. This is where most Sprint Reviews fall flat — the demo shows what was built but not why it matters. AI helps you craft the value narrative that keeps stakeholders engaged and demonstrates business alignment. AI is also excellent at preparing for difficult conversations in the Sprint Review. If your team missed the Sprint Goal, use AI to help you draft a clear, honest explanation that covers what happened, what was learned, and what process changes will prevent recurrence. Having this language prepared prevents defensive improvisation in the moment, which stakeholders find far less reassuring than a calm, structured explanation. After the Sprint Review, use AI to process the stakeholder feedback and generate a prioritized list of backlog items based on what was discussed. This turns your Sprint Review output into actionable refinement inputs within minutes of the meeting ending.`,

  '6c7df931-ca0b-4e90-a8a4-9cf95c589ba6': `Lesson 3.4 — AI-Driven Retrospectives: Deeper Insights, Better Actions. The Sprint Retrospective is the most underutilized ceremony in most Scrum teams. It happens, it generates sticky notes or a list of items, some action items get created, and then nothing much changes. The core problem is analysis depth — teams rarely have time to look across multiple sprints for patterns, correlate impediments with outcomes, or connect team dynamics to delivery metrics. AI solves the analysis problem. Here is how to run an AI-enhanced retrospective. Before the retrospective, use AI to analyze the last three to five sprints of data: velocity trends, impediment patterns, story completion rates, and any available team satisfaction data. Ask AI to identify the top three systemic issues — patterns that appear repeatedly across sprints — and distinguish them from one-off problems that occurred in a specific sprint. This pre-analysis gives your retrospective a data foundation rather than relying entirely on what team members remember or feel comfortable saying. During the retrospective, use AI-generated insights as conversation starters rather than conclusions. Show the team the pattern analysis and ask: does this match your experience? What is the root cause behind this pattern? This approach surfaces systemic issues that might not emerge from a standard Start-Stop-Continue exercise. For action item generation, use AI to evaluate proposed actions against your team's historical execution patterns. If your team consistently creates retrospective action items that never get done, AI can help you identify which types of actions your team actually executes versus which ones get forgotten. Over time, this calibration improves the quality of your retrospective commitments. After the retrospective, use AI to update your team's retrospective history document — a running record of themes, actions committed, and actions completed. This document becomes invaluable when you are coaching team development or preparing for quarterly reviews.`,

  'da8d86c3-098a-478c-9638-e08254a781ec': `Lesson 3.5 — Notion AI and Gamma for PM Documentation. Documentation is the unsexy but essential foundation of project management. Good documentation enables team alignment, onboarding efficiency, stakeholder trust, and institutional knowledge preservation. Bad documentation — or no documentation — creates confusion, rework, and organizational risk. AI has transformed documentation from a burden into a competitive advantage. Notion AI is the most powerful AI documentation tool for project teams. It is built directly into the Notion workspace, so there is no switching between tools. The most valuable features for PMs are AI-powered page summarization, which generates a concise summary of any long document and is perfect for onboarding new team members to existing project context; AI writing assistance, which helps you write clearer, more structured documentation from rough notes; and the ability to ask questions about your Notion workspace and receive AI-synthesized answers drawn from multiple pages. The practical workflow is this: after any significant meeting or decision, spend 5 minutes writing rough notes in Notion. Then ask Notion AI to turn those notes into a properly structured document with clear headings, action items highlighted, and key decisions called out. What previously took 30 minutes of careful writing now takes 5 minutes of rough input plus 2 minutes of AI polish. Gamma is a different tool — it is an AI-powered presentation builder that turns written content into professional slide decks. For PMs who need to prepare project status presentations, stakeholder briefings, or process documentation slides, Gamma dramatically reduces presentation creation time. Give it your status report text or your meeting notes and it generates a slide deck with professional design, appropriate structure, and visual hierarchy. You customize the details and brand, but the structural work is done. Together, Notion AI and Gamma give you a documentation and communication stack that keeps pace with the speed of your projects rather than lagging behind it.`,

  '05a56822-92d3-4350-8101-ad07f491bffd': `Lesson 3.6 — Lab: Automate Your Entire Communication Workflow. Welcome to the Module 3 capstone lab. Today we build something that I genuinely believe will be the most valuable deliverable of this entire course: a fully automated communication workflow. When we finish, your meeting summaries, stakeholder reports, sprint documentation, and team updates will flow automatically through a connected pipeline with minimal manual intervention. The workflow has five components that connect together. Component one is meeting capture. Otter.ai or Fireflies joins every meeting, transcribes it, and sends the raw transcript to a Notion database automatically via Zapier. No manual copy-paste. The transcript lands in Notion within minutes of the meeting ending. Component two is AI summarization. A Notion automation or Zapier workflow triggers Claude or ChatGPT to process the raw transcript and generate a structured summary using your custom template — decisions, action items, risks, and next steps. The summary is appended to the Notion page automatically. Component three is team distribution. When the summary is complete, a Zapier workflow posts a formatted version to your team's Slack channel and tags the relevant action item owners. Everyone is informed within 15 minutes of any meeting ending without any manual effort from you. Component four is status report generation. At a scheduled time each week, a workflow pulls the week's meeting summaries and sprint data from Notion, sends them to AI for synthesis, and generates a draft status report that lands in your drafts folder for your 10-minute review and approval. Component five is the archive. All meeting notes, summaries, decisions, and status reports are automatically organized in a searchable Notion database by project, sprint, and date. Your institutional knowledge is preserved and accessible. Build this workflow once and it runs indefinitely. The initial setup takes 3 to 4 hours. The ongoing time savings are 5 to 8 hours per week. Congratulations on completing Module 3.`,

  // AI MASTERY MODULE 4
  '287f7061-d9a1-4a1b-a558-de30a0475d6e': `Welcome to Module 4, Lesson 4.1 — GitHub Copilot and Cursor: What PMs Need to Know. I want to start with a question that I hear from PM students: Professor Didier, I am a PM or Scrum Master, not a developer. Why do I need to know about coding tools? Here is why: if you do not understand what your developers are working with, you cannot remove their impediments effectively, you cannot plan capacity accurately, and you cannot have credible conversations with your engineering leads about what AI can and cannot accelerate. Let me give you the PM-level understanding you need. GitHub Copilot is an AI pair programmer embedded directly in VS Code, JetBrains, and other IDEs. It suggests code completions, writes entire functions, and generates unit tests in real time. GitHub's own research shows developers using Copilot complete tasks about 55 percent faster and report significantly higher job satisfaction. For your capacity planning, this means you should expect to see velocity improvements of 20 to 40 percent in teams that adopt Copilot — but only after a two to three sprint ramp-up period while developers learn to work effectively with the tool. Cursor takes a different approach — it is an entire IDE built around AI from the ground up. It has deeper codebase awareness, meaning it can understand how your team's services connect and generate suggestions that fit your specific architecture rather than generic patterns. Teams that switch to Cursor from VS Code with Copilot typically see another 15 to 25 percent improvement in developer productivity after the adjustment period. Here is what you actually need to manage as a PM or Scrum Master. First, protect the ramp-up period. Do not increase sprint scope the week after Copilot adoption — developers need time to calibrate. Second, track meaningful metrics: PR cycle time, bug introduction rate, and developer satisfaction. Not lines of code. Third, support developers who struggle with AI tools rather than pressuring them to adopt. Investigate why the tool is not working for them. Fourth, understand that these tools shift developer work from mechanical to strategic. Your best developers will have more mental capacity for architecture decisions and complex problem-solving.`,

  '04388c71-c9ab-4e61-b3b9-8b22756f9bd6': `Lesson 4.2 — AI-Powered Code Review and Pull Request Management. Code review is one of the most significant bottlenecks in software delivery, and it is a bottleneck that project managers and Scrum Masters can directly influence. Tools like CodeRabbit, GitHub Copilot code review, and Amazon CodeGuru are transforming the code review process by providing instant first-pass review on every pull request the moment it is opened. Let me explain what this means for your delivery metrics. In a traditional code review process, a PR is opened and then waits — sometimes for hours, sometimes for days — for a senior developer to have capacity to review it. The developer who opened the PR context-switches to other work. When the review finally arrives, they have to context-switch back, which costs 15 to 20 minutes of cognitive reorientation. If the review generates comments, the back-and-forth cycle repeats. AI code review eliminates the waiting and reduces the cycle. The AI provides feedback within seconds of the PR being opened — catching syntax issues, security vulnerabilities, style violations, and common bugs. By the time a human reviewer looks at the PR, the mechanical issues are already resolved, allowing the human reviewer to focus entirely on architecture decisions, business logic correctness, and knowledge transfer. The impact on your metrics is significant. Teams using AI code review typically see time-to-first-review drop from hours to minutes, overall PR cycle time reduce by 40 to 60 percent, and senior developer time freed from reviewing formatting issues to doing higher-value architectural mentoring. As the Scrum Master, your role in AI code review adoption is to frame it correctly to your senior developers. The risk is that experienced developers feel their expertise is being devalued. The reframe is: AI handles the tedious mechanical layer so you can focus on the architectural and mentoring conversations that only you can have. Most senior developers, once they experience this in practice, become the strongest advocates for AI code review because it makes their work more interesting and more impactful.`,

  '2b460dce-345a-4d36-9106-49e1978e86d1': `Lesson 4.3 — AI for Test Automation and Quality Assurance. Testing is often the bottleneck that nobody wants to talk about in sprint planning. Stories are developed, they sit in a ready-to-test state, and the QA queue backs up because manual testing is slow and test case writing is time-consuming. AI is transforming both the speed and the coverage of testing in ways that directly affect your sprint throughput. Let me walk you through the key AI testing capabilities and their PM implications. AI test case generation takes a user story or feature specification and automatically generates comprehensive test cases covering happy paths, edge cases, error conditions, and boundary values. Tools like Testim, Mabl, and Copilot for test generation can produce 20 to 30 test cases for a well-written story in minutes — work that previously took a QA engineer 2 to 3 hours. The coverage improvement is often significant: AI consistently identifies test scenarios that humans miss, particularly around error handling and state management edge cases. AI test maintenance is solving one of the biggest problems in test automation: tests breaking when the UI changes. Traditional automated tests are brittle — a button changing position or color breaks hundreds of tests. Self-healing test tools like Mabl and Testim use AI to automatically adapt tests when the application changes, dramatically reducing test maintenance overhead. For capacity planning, this means your QA capacity is no longer purely a function of story count — it scales better as test automation handles more regression coverage. The PM and Scrum Master implications are concrete. In sprint planning, you can commit to more stories when you have strong AI-powered test automation coverage because the regression risk is lower. In sprint reviews, you can demonstrate quality metrics — defect escape rate, test coverage — that give stakeholders confidence in the release. And in retrospectives, you can track testing bottlenecks with data and use AI analysis to identify whether the constraint is test case creation, test execution, or defect resolution.`,

  '41613e14-0b3e-41ce-8331-765a852089cb': `Lesson 4.4 — CI/CD Pipeline Optimization with AI. Continuous Integration and Continuous Deployment pipelines are the heartbeat of modern software delivery. When they work well, teams deploy with confidence multiple times per day. When they are slow, flaky, or poorly configured, they become a source of frustration, delivery bottlenecks, and lost developer productivity. AI is being applied to CI/CD optimization in several high-impact ways, and as a PM or Scrum Master, understanding these capabilities helps you have more informed conversations with your engineering team about delivery infrastructure. Intelligent test selection is one of the highest-impact AI applications in CI/CD. Traditional pipelines run the entire test suite on every code change — which can take 30 to 90 minutes for large codebases. AI-powered test selection analyzes which tests are most likely to fail based on which code was changed and runs those tests first. Teams using intelligent test selection see pipeline run times reduce by 40 to 70 percent, which means faster feedback for developers and faster deployment cycles for the business. Flaky test detection is another area where AI delivers immediate value. Flaky tests — tests that sometimes pass and sometimes fail without any code change — are a massive source of developer frustration and trust erosion in CI/CD systems. AI tools can identify flaky tests by analyzing historical test result patterns and quarantine them automatically, keeping your pipeline reliable while the team investigates and fixes the underlying instability. Deployment risk analysis uses AI to analyze the scope of each deployment — which services are being changed, what their dependency graph looks like, what historical failure patterns exist — and generates a risk score and deployment recommendation. High-risk deployments might be flagged for additional manual review or staged rollout. This reduces deployment anxiety and production incidents. As a PM, tracking deployment frequency and change failure rate as DORA metrics — and using AI analysis to improve them — gives you a data-driven conversation with engineering leadership about delivery health.`,

  '07be1133-ef62-4954-9fe4-b860692f75d0': `Lesson 4.5 — AI Monitoring and Incident Response with Datadog. When production incidents happen — and they will — the speed of detection, diagnosis, and resolution directly affects your customers, your stakeholders, and your team's morale. Historically, incident response was highly manual: someone noticed an alert, assembled a team, spent significant time diagnosing root cause, and then resolved the issue. AI-powered monitoring tools like Datadog, New Relic, and Dynatrace are transforming this process. Let me explain what this means for you as a PM or Scrum Master. AI-powered anomaly detection establishes baseline patterns for your system's normal behavior — request rates, error rates, latency percentiles, resource utilization — and automatically alerts when behavior deviates from those baselines in ways that suggest a problem before users start complaining. Traditional threshold-based alerting catches obvious problems. AI anomaly detection catches subtle degradations that precede catastrophic failures. The PM implication: fewer surprise production crises because issues are caught earlier. AI-assisted root cause analysis is perhaps the highest-value feature. When an incident occurs, Datadog's Watchdog AI analyzes logs, metrics, traces, and deployment history to identify the likely root cause and the contributing factors. What previously required a senior engineer to spend 30 to 60 minutes correlating data across multiple dashboards now happens automatically in minutes. For Scrum teams, this means shorter incidents, less after-hours emergency work, and more confident deployments because the team knows that if something goes wrong, AI will help them find and fix it quickly. For your sprint planning and risk management, understanding your team's mean time to recovery — MTTR — and tracking it as a metric gives you visibility into an important dimension of team performance that purely velocity-based metrics miss. Teams with strong AI-powered observability consistently have better MTTR because they identify and resolve issues faster.`,

  'b906bb57-f7df-40a9-80d0-69430892b987': `Lesson 4.6 — Vercel AI and Deployment Intelligence. Deployment is the moment of truth in software delivery. Everything your team built during the sprint gets released to real users, and the quality of that deployment experience — for both the engineering team and end users — significantly affects team confidence, delivery frequency, and business outcomes. Modern deployment platforms like Vercel have integrated AI capabilities that are changing what safe, fast deployment looks like. Vercel's deployment intelligence analyzes each deployment using AI to provide several categories of insights that are directly relevant to PM and Scrum Master decision-making. Build performance analysis tracks how long builds take over time and identifies regressions — cases where a specific code change caused build time to increase significantly. This matters for your delivery pipeline because slow builds reduce deployment frequency and developer productivity. AI-flagged build regressions help engineering teams address performance issues before they compound. Deployment risk scoring evaluates each deployment based on the size of the change, the blast radius if something goes wrong, and historical patterns for the components being deployed. A small CSS change has a different risk profile than a database migration — Vercel's AI helps teams treat them differently. Preview deployments with AI-powered visual regression testing automatically compare the visual appearance of the new deployment against the previous version and flag unexpected visual changes. This catches UI bugs before they reach production without requiring a dedicated manual QA pass on every deployment. For Scrum teams practicing continuous deployment, this means every story can be deployed independently and validated automatically, which removes a major synchronization constraint from sprint planning. Teams no longer need to batch work into large releases to justify the QA overhead — each story can be deployed and validated as soon as it is complete. This is the foundation of true continuous delivery.`,

  'd64eeb17-08d6-4367-b2ed-49a286f60235': `Lesson 4.7 — Lab: Measuring and Reporting AI Impact on Delivery Velocity. Welcome to the Module 4 lab. This lab is different from the others — instead of building a workflow, we are building a measurement system. Because you cannot improve what you cannot measure, and you cannot justify continued AI investment without data. By the end of this lab, you will have a dashboard that tracks the AI impact on your team's delivery performance. The metrics that matter most for AI impact measurement fall into four categories. Delivery speed metrics: deployment frequency, lead time from commit to production, and PR cycle time. These are the DORA metrics that most accurately reflect delivery pipeline performance. Before your team adopted AI tools, what were these numbers? You need a baseline to measure against. Quality metrics: change failure rate — the percentage of deployments that cause production incidents — bug escape rate from sprint to production, and test coverage percentage. AI-powered testing and code review should improve all three of these over time. Team productivity metrics: story cycle time from creation to done, velocity trend over rolling three-sprint windows, and the percentage of sprint goals achieved. These metrics connect AI tool adoption to business outcomes that leadership cares about. Developer experience metrics: these are often overlooked but critically important. Survey your developers monthly on cognitive load, time spent on repetitive tasks, and overall job satisfaction. AI adoption that improves delivery metrics but burns out your team is not sustainable. The dashboard itself should be built in whatever tool your team already uses — Jira dashboards, Notion, or a dedicated analytics tool. The key is that it is visible to the whole team and updated automatically from your existing data sources. Present this dashboard in your Sprint Review every quarter with a narrative about AI impact. When leadership sees that AI tools are producing measurable improvements in delivery speed and quality, continued investment and adoption become much easier to justify.`,

  // AI MASTERY MODULE 5
  'e7f6b9ce-eaa7-474c-a397-3424f8f37814': `Welcome to Module 5, Lesson 5.1 — Predictive Analytics for Sprint and Project Forecasting. One of the most stressful aspects of project management is answering the question that every stakeholder asks: when will this be done? Traditional forecasting methods — simple velocity averaging, burn-down charts, manual estimation — are often wrong in ways that erode stakeholder trust and create planning chaos. Predictive analytics powered by AI gives you a more accurate, more defensible answer to that question. Let me explain how it works and how to use it. Monte Carlo simulation is the gold standard for sprint and project forecasting, and modern AI tools make it accessible without requiring data science expertise. The approach is simple: instead of calculating a single deterministic estimate, you run thousands of simulated scenarios based on your historical velocity distribution. The output is a probability distribution — for example, there is a 50 percent probability you complete this work in 8 sprints, an 85 percent probability in 11 sprints, and a 95 percent probability in 13 sprints. This is dramatically more honest and useful than a single-point estimate that everyone knows is uncertain. Tools like ActionableAgile, Nave, and built-in Jira features now provide Monte Carlo forecasting from your existing project data with minimal setup. Once configured, you run a new forecast at the start of each sprint and show stakeholders the probability distribution rather than a single date. This changes the conversation from why are you behind schedule to let us discuss what trade-offs we want to make to improve our probability of the target date. AI-enhanced forecasting also identifies the factors most correlated with your team's delivery variance — scope creep, specific types of technical work, team composition changes, dependencies on external teams. This analysis helps you proactively address the root causes of unpredictability rather than constantly reacting to forecast misses.`,

  'd7f550d1-8a56-44f9-80c1-a7fb605285f8': `Lesson 5.2 — AI Risk Scoring and Early Warning Systems. Risk management in most projects is reactive — risks are identified during planning, added to a risk register, and then largely ignored until they become issues. The problem is that the most damaging risks are the ones that were not on the register: the dependencies that quietly slipped, the team member who was struggling but not asking for help, the technical debt that compounded until it became a sprint crisis. AI-powered early warning systems change risk management from reactive to proactive. Here is how they work and how to implement them. Velocity anomaly detection analyzes your team's sprint-by-sprint velocity pattern and alerts when current-sprint progress deviates from the historical pattern in ways that suggest the sprint is at risk. If your team typically completes 40 percent of their sprint work in the first week and you are currently at 20 percent, the system flags this on day 7 — giving you time to intervene rather than discovering the miss on the last day of the sprint. Dependency risk scoring monitors your backlog for items with external dependencies and tracks whether those dependencies are on track. Blocked items that are on the critical path receive elevated risk scores that surface in your daily standup view rather than being buried in a Jira board. Team health signals — derived from standup patterns, pull request activity, and meeting engagement — can indicate when a team member is struggling before it manifests as a velocity drop. This requires careful implementation to avoid feeling like surveillance; the goal is supportive coaching, not performance monitoring. The practical implementation starts simple: configure your project management tool's built-in risk indicators, set up a weekly AI analysis of your sprint data against your historical patterns, and create a risk dashboard that you review every Monday morning. Within two to three sprints, you will start catching problems earlier and resolving them before they derail your sprint goals.`,

  '306cb1d4-236a-422e-a24a-bd036b1989ad': `Lesson 5.3 — Resource Optimization and Capacity Planning with AI. Capacity planning is one of the most challenging aspects of sprint planning — estimating how much work your team can realistically complete in the upcoming sprint given actual availability, considering holidays, meetings, on-call rotations, and the inevitable context-switching overhead. AI-powered capacity planning tools significantly improve the accuracy of these estimates. Traditional capacity planning asks developers to estimate their available hours and then PMs manually calculate capacity. This is imprecise because it does not account for the difference between hours available and hours productive, the impact of context switching, or patterns in how specific types of work affect team throughput. AI-enhanced capacity planning uses historical data to build more accurate capacity models. If your team consistently completes 75 percent of their committed points when they have three team members on-call versus 95 percent when nobody is on-call, your AI capacity model captures this pattern and automatically adjusts your sprint capacity recommendation. Skill-based capacity planning is another area where AI adds significant value. Your team is not interchangeable — a sprint that requires three complex backend integrations has a different effective capacity than a sprint focused on frontend feature work, even if the story point total is identical. AI tools that track which team members complete which types of stories can identify bottlenecks before they occur and suggest story assignments that optimize throughput. For remote and distributed teams, AI tools that analyze communication patterns and collaboration networks can identify when team members are working in isolation in ways that increase coordination risk. This is particularly valuable for Scrum Masters trying to maintain team cohesion across time zones and work styles.`,

  '55476150-730e-47e4-8335-ca85e6b61895': `Lesson 5.4 — AI-Enhanced Burndown and Burnup Analysis. Burndown and burnup charts are the classic Scrum progress visualization tools, and they remain valuable — but they are often misread and misused. Traditional burndown analysis is visual and intuitive, but it lacks the analytical depth to distinguish between common causes of burndown deviations. AI-enhanced analysis adds that depth. Let me explain what AI adds to these familiar charts. Pattern recognition across multiple sprints is AI's primary contribution to burndown analysis. A human reviewing a burndown chart sees whether the line is above or below the ideal trajectory. AI analyzing 20 sprints of burndown data sees that your team consistently shows a flat burndown for the first three days of every sprint, then accelerates in days four through eight, then has a gap between committed and completed on the last day. This pattern suggests a specific problem — likely that stories are not broken down into small enough increments to show progress early in the sprint. That insight leads to a specific process improvement rather than a general admonition to do better. Scope change detection is particularly valuable. AI can distinguish between a burndown deviation caused by scope addition, scope removal, estimation error, and actual delivery slowdown — four very different problems that require very different responses. When you can show a stakeholder that the burndown deviation was caused by three scope additions that they approved, the conversation is very different than if you simply show a chart that missed the line. Burnup analysis — which shows both work completed and total scope — benefits from AI trend analysis that projects when the completion line will intersect the scope line based on current velocity and historical scope change patterns. This gives stakeholders a probabilistic release date that updates automatically as sprint data accumulates, replacing the static estimates that quickly become outdated.`,

  'b81bc0f4-cb8e-4947-814d-81a08fdb2d15': `Lesson 5.5 — Data-Driven Decision Making with AI Analysis. The highest-value application of AI for project managers and Scrum Masters is not automating tasks — it is improving the quality of decisions. Every week you make dozens of decisions: which stories to prioritize, how to respond to a scope change request, whether to add a team member to an at-risk sprint, how to communicate bad news to stakeholders. Most of these decisions are made under time pressure with incomplete information and the cognitive limitations that come from being busy and slightly stressed. AI analysis cannot make these decisions for you — they require context, relationships, and judgment that only you have. But AI can dramatically improve the information quality that feeds those decisions. Here is a framework for AI-assisted decision making that I use in my own work. Step one is decision framing. Before you ask AI for analysis, be explicit about what decision you are making and what information would change your choice. Vague questions get vague answers. Specific questions get useful analysis. Step two is data gathering. Collect the relevant data points — historical patterns, comparable situations, known constraints — and give them to AI as context. The more relevant context you provide, the more useful the analysis. Step three is analysis generation. Ask AI to analyze the data and identify the key factors, trade-offs, and risks associated with each option. Ask it specifically to identify what you might be missing or what assumptions your framing makes. Step four is critical review. Apply your professional judgment to the AI's analysis. Where does it align with your intuition? Where does it conflict? Conflicts deserve investigation — sometimes AI sees something you missed, sometimes AI lacks context that changes the conclusion. Step five is documentation. Record the decision, the key factors that drove it, and the AI analysis that informed it. This creates an institutional knowledge base of how your team makes decisions and why, which is invaluable for retrospectives and for onboarding future team members.`,

  '17960fae-f8a5-4843-ac4d-c2b85e56e6aa': `Lesson 5.6 — Lab: Build Your AI-Powered Project Health Dashboard. Welcome to the Module 5 lab. Today we build the Project Health Dashboard — a real-time view of your project's critical health indicators, powered by AI analysis and updated automatically from your existing project data. This is the artifact that will make you the most informed person in every status meeting you attend. The dashboard has six panels. Panel one is Delivery Health, showing current sprint velocity versus three-sprint rolling average, Sprint Goal achievement rate over the last five sprints, and trend direction — improving, stable, or declining. This panel answers the question: is our delivery getting better or worse? Panel two is Predictive Forecast, showing the Monte Carlo probability distribution for your release date based on current velocity and remaining backlog. Update this every sprint and show stakeholders the confidence interval rather than a single date. Panel three is Risk Radar, showing your top five active risks with likelihood and impact scores, the velocity at which each risk is changing, and the recommended mitigation actions. AI updates this panel by analyzing sprint data and flagging new risk patterns. Panel four is Quality Indicators, showing bug escape rate, test coverage trend, and change failure rate. These metrics tell you whether you are accumulating technical debt faster than you are addressing it. Panel five is Team Health, showing capacity utilization, impediment resolution time, and a simple team satisfaction trend from your weekly pulse check. Panel six is Stakeholder Alignment, showing the date of your last stakeholder update, open decision items requiring stakeholder input, and any scope change requests pending review. Build this dashboard in Notion, Jira, or a dedicated analytics tool. Configure AI to generate a weekly narrative summary of the dashboard trends — two paragraphs that tell the story behind the numbers. This narrative is what you share in your executive status update.`,

  // AI MASTERY MODULE 6
  'af519a83-033d-4ef3-9a2f-0a15a0b3e0d6': `Welcome to Module 6, Lesson 6.1 — Creating Custom GPTs for Your PM Workflow. We have reached the most advanced module in this course, and today we are going to build something that will genuinely change how you work: your own custom AI assistant, trained specifically for your role, your team's context, and your organization's standards. Custom GPTs and AI assistants are no longer a developer-only capability. With ChatGPT's GPT Builder and Claude's Projects feature, you can create a specialized AI assistant in about an hour — no coding required. Let me show you what this looks like for a PM or Scrum Master. A Custom PM Assistant is configured with your organization's specific context: your team's Definition of Done, your stakeholder communication standards, your risk management framework, your sprint retrospective format, and examples of your best-quality work. When you give this assistant a task, it does not produce generic output — it produces output calibrated to your standards and context. The practical applications are numerous. Your Custom PM Assistant can write stakeholder status reports in your organization's exact format and tone. It can review user stories against your specific Definition of Ready criteria rather than generic best practices. It can generate retrospective analysis using your team's preferred frameworks. It can draft escalation emails in your organization's communication style. Building the custom assistant requires three components: a system prompt that defines the assistant's role, capabilities, and constraints; uploaded context documents — your templates, your standards documents, examples of good work; and custom instructions that define how the assistant should handle specific types of requests. The investment is two to three hours of upfront configuration. The return is an AI assistant that saves you 30 to 60 minutes per day, indefinitely.`,

  '3aec215b-f022-4777-9214-48a9eed4beba': `Lesson 6.2 — Workflow Automation with Zapier and Make. Zapier and Make are the connective tissue of the modern AI-powered PM workflow. They allow you to connect your project management tools, communication platforms, AI services, and documentation systems into automated workflows that run without your manual intervention. Let me walk you through the most high-value automation patterns for PMs and Scrum Masters. The meeting-to-documentation pipeline is typically the first automation teams implement and the one with the most immediate impact. The workflow: meeting ends, Otter.ai sends transcript to Zapier, Zapier sends transcript to Claude or ChatGPT for summarization, AI summary is posted to the relevant Notion project page, and a formatted version is posted to Slack with action items tagged to responsible team members. This entire sequence runs automatically within 15 minutes of every meeting ending, requiring zero manual effort from the PM. The incident response notification workflow monitors your monitoring tools for alerts above a threshold severity, automatically creates a Jira incident ticket, notifies the on-call developer and Scrum Master via Slack with a pre-formatted incident response template, and starts a shared incident timeline document in Notion. When the incident is resolved, the workflow automatically updates the ticket and sends a stakeholder notification. The sprint metrics digest compiles your weekly sprint data every Friday afternoon, sends it to AI for analysis, and delivers a formatted digest to your Slack channel with velocity trends, upcoming risks, and the top three action items for the following week. No manual compilation, no forgotten metrics, consistent every week. Make — formerly Integromat — offers more complex automation logic than Zapier and is preferred for workflows that require conditional branching or data transformation. Use Zapier for simple trigger-action workflows and Make for workflows with multiple conditions or data processing steps.`,

  '82c0dd36-5905-4935-8d9c-5bd88dbe7f72': `Lesson 6.3 — Building AI-Integrated Dashboards. A great project management dashboard is not a collection of charts — it is a decision support system. It should answer the questions your stakeholders will ask before they ask them, surface the risks that need attention before they become crises, and give your team a shared understanding of project health without requiring anyone to dig through data manually. AI-integrated dashboards take this further by adding predictive capabilities, pattern recognition, and natural language summaries that static charts cannot provide. Let me walk you through building a truly effective AI-integrated dashboard. The foundation is connecting your data sources: Jira or Linear for story and sprint data, GitHub or GitLab for code metrics, your monitoring tool for production health, and your team calendar for capacity data. Most modern dashboard tools — Datadog, Grafana, Notion, or dedicated PM tools — have native integrations with these sources. The AI integration layer sits on top of this data foundation. At a scheduled interval — daily or weekly depending on your team's cadence — an AI workflow analyzes the latest data across all sources and generates three outputs: an anomaly report flagging any metric that has moved outside its normal range, a trend narrative summarizing the direction your key metrics are moving and what that means for your sprint and release plan, and a recommended action list with the two or three most impactful things you should do this week based on the data. The natural language summary is the most underrated component. Many stakeholders will not engage with charts, but they will read a well-written two-paragraph summary of project health. AI makes it practical to produce this summary every week without it consuming significant time. The result is a dashboard that does not just show data — it tells the story of your project's health in a way that drives informed decisions and builds stakeholder confidence.`,

  '26c40002-05f5-4f15-8322-4f7c54838d82': `Lesson 6.4 — Prompt Libraries and Templates for PM and Scrum Master. The quality of your AI interactions is almost entirely determined by the quality of your prompts. A vague prompt produces a generic, often useless response. A well-crafted prompt with the right context, the right constraints, and the right output format specification produces professional-quality work that requires minimal editing. Building and maintaining a prompt library is one of the highest-leverage investments you can make in your AI productivity. Let me give you the core prompts that every PM and Scrum Master should have in their library. The sprint planning prompt: You are an experienced Agile coach. Based on the following team velocity data, backlog items, and team capacity, generate a recommended sprint plan with a Sprint Goal, a rationale for the selected stories, estimated sprint risks, and three questions the team should discuss during Sprint Planning. The retrospective analysis prompt: You are a team coach analyzing sprint performance data. Review the following sprint metrics and team feedback and identify the top three systemic issues — patterns that appear across multiple sprints — their likely root causes, and specific actionable recommendations for each. The stakeholder communication prompt: You are a senior PM writing an executive status update. The audience has limited technical context. Using the following project data, write a status report with RAG status, executive summary in plain language, key accomplishments, risks requiring stakeholder attention, and any decisions needed from leadership. The impediment resolution prompt: I am a Scrum Master dealing with the following impediment. Analyze the root cause, identify who in a typical organization has the authority to resolve it, suggest three approaches to resolution ranging from quick workaround to permanent fix, and identify what information I need to gather before escalating. Each of these prompts should be stored in your prompt library with notes on when to use them and any customizations relevant to your specific context.`,

  '8635e903-230b-49c8-8a0f-abe999b3a8db': `Lesson 6.5 — Staying Current: The AI Tool Landscape in 2025 and 2026. The AI tool landscape is evolving faster than any technology shift I have seen in my career. Tools that were cutting-edge six months ago are now standard, and capabilities that seemed years away are shipping today. For project managers and Scrum Masters who want to remain at the forefront of AI adoption in their teams, staying current is an ongoing professional responsibility. Let me give you a framework for staying current without being overwhelmed. First, identify your learning channels. The most reliable signal sources for PM-relevant AI developments are the Atlassian, GitHub, and Linear product blogs for project management tool updates; the AI in Product Management and Agile community forums on LinkedIn; and the release notes and changelog pages for the specific tools your team uses. Set up a weekly digest using a tool like Feedly or just a bookmarked RSS reader that surfaces updates from these sources in one place. Second, practice rapid evaluation. When a new AI tool or feature gets significant attention in your network, give yourself 30 minutes to evaluate it against the five-criteria framework from Module 1: integration fit, output quality, learning curve versus time savings, security, and measurability. If it passes two or three criteria in the initial evaluation, dedicate a focused pilot. If not, note it and revisit in three months. Third, build a network of AI-forward practitioners. The fastest way to stay current is to be connected with people who are actively experimenting with AI tools in PM and Scrum contexts. LinkedIn is excellent for this. Follow practitioners who share specific, hands-on experiences rather than general AI hype. The AI landscape will continue to accelerate. Your competitive advantage is not knowing every tool — it is having a systematic process for evaluating and adopting the ones that genuinely improve your team's performance.`,

  'a3d8dd77-c290-4e44-ae63-922e63f213f0': `Lesson 6.6 — Capstone Project: Design Your AI-Powered PM Operating Model. You have reached the final lesson of the AI Mastery course, and I want you to leave with something concrete and personal: your own AI-Powered PM Operating Model. This is not a generic framework — it is a specific, practical design for how you will use AI in your daily work as a PM or Scrum Master, tailored to your role, your team, and your organization. The operating model has five components. Component one is your daily AI workflow — a specific sequence of AI-assisted activities you will perform every working day. This might include: reviewing the AI-generated overnight monitoring summary before your first standup, using AI to prep your standup talking points based on yesterday's Jira activity, and ending the day by dictating rough notes that AI formats into Notion documentation. Component two is your ceremony enhancement plan — specifically how you will use AI before, during, and after each Scrum ceremony. Be specific: before refinement I run AI story analysis, during planning I use AI estimation reference, after retro I use AI to identify pattern themes. Component three is your stakeholder communication system — the automated pipeline that produces status reports, meeting summaries, and stakeholder notifications with minimal manual effort. Component four is your metrics dashboard — the specific metrics you track, the AI analysis that surfaces insights from those metrics, and the cadence at which you review and share them. Component five is your learning commitment — the specific channels you follow, the monthly time you invest in evaluating new tools, and the network of practitioners you learn from. Write this operating model as a one-page document. Review and update it every quarter. Share it with your manager as evidence of your professional development. This document is your competitive advantage in a profession that is being transformed by AI. Congratulations on completing the AI Mastery course. Solo excelencia.`,
};

async function run() {
  const ids = Object.keys(transcripts);
  console.log(`Seeding ${ids.length} lessons...`);
  for (const id of ids) {
    const { error } = await supabase
      .from('videos')
      .update({ translations: { en: { transcript: transcripts[id] } } })
      .eq('id', id);
    if (error) console.error('❌', id, error.message);
    else console.log('✅', id);
  }
  console.log('Done with batch 2.');
}
run();
